mapper.select:
select id, org_name as organization, alias, org_owner, tenant_id as tenant_id, parent_id as parent_id, org_rank as org_rank, created_at as created_at, remarks, parent_keys as parent_keys, org_category, enabled, org_type, order_no from la_organization o
o.enabled = 1
and o.org_owner = #{parameters.owner}
and o.org_owner is null
and o.id in
#{item}
and o.tenant_id = #{parameters.tenantId}
and o.tenant_id is null
order by o.org_rank, o.order_no, o.parent_id, o.org_name

select id, org_name as organization, alias, org_owner, tenant_id as tenant_id, parent_id, org_rank as org_rank, created_at , remarks, parent_keys as parentKeys, org_category, enabled, org_type, order_no from la_organization o
and o.org_owner = #{parameters.owner}
and o.org_owner is null
and o.org_name like #{parameters.name}
and o.alias like #{parameters.alias}
and o.id in
#{item}
and o.tenant_id = #{parameters.tenantId}
and o.tenant_id is null
order by o.org_rank, o.order_no, o.parent_id, o.org_name

select id, alias as name, parent_id as pid
from la_organization o
where o.enabled = 1



            and o.org_owner = #{parameters.owner}


            and o.org_owner is null




    and o.parent_keys like #{parameters.parentKeys}



        and o.tenant_id = #{parameters.tenantId}


        and o.tenant_id is null


order by o.org_rank, o.order_no, o.parent_id, o.org_name

mapper.update:
update la_users t set t.enabled = #{enabled} where t.username in (
    select t2.username from la_user_organization t2
    inner join la_organization t3 on t2.organization_id = t3.id
    where t3.id in
    #{item}
)

update la_organization t set
t.org_rank = case

    when id = #{item.id} then #{item.level}

end,
parent_id = case

    when id = #{item.id} then #{item.parentId}

end,
parent_keys = case

    when id = #{item.id} then #{item.parentKeys}

end,
order_no = case

    when id = #{item.id} then #{item.orderNo}

end
where id in

    #{item.id}
